        /// <summary>Aggregates partial signatures</summary>
        /// <param name="sig64">complete (but possibly invalid) Schnorr signature In:       session: pointer to the session that was created with musig_nonce_process partial_sigs: array of pointers to partial signatures to aggregate n_sigs: number of elements in the partial_sigs array. Must be greater than 0.</param>
        /// <param name="session">pointer to the session that was created with musig_nonce_process partial_sigs: array of pointers to partial signatures to aggregate n_sigs: number of elements in the partial_sigs array. Must be greater than 0.</param>
        /// <param name="partial_sigs">array of pointers to partial signatures to aggregate</param>
        /// <returns>0 if the arguments are invalid, 1 otherwise (which does NOT mean the resulting signature verifies).</returns>
        public bool MusigPartialSigAgg(Span<byte> sig64, ReadOnlySpan<byte> session, byte[][] partial_sigs)
        {
            if (partial_sigs == null || partial_sigs.Length == 0)
                throw new ArgumentException($"{nameof(partial_sigs)} must not be null or empty");
            for (int i = 0; i < partial_sigs.Length; i++)
            {
                if (partial_sigs[i] == null || partial_sigs[i].Length < 36)
                    throw new ArgumentException($"{nameof(partial_sigs)}[{i}] must be at least 36 bytes");
            }
            if (sig64.Length < 64)
                throw new ArgumentException($"{nameof(sig64)} must be at least 64 bytes");
            if (session.Length < 133)
                throw new ArgumentException($"{nameof(session)} must be at least 133 bytes");

            var count = partial_sigs.Length;
            var ptrSize = IntPtr.Size;
            var nativePtrArray = Marshal.AllocHGlobal(ptrSize * count);
            try
            {
                fixed (byte* sig64Ptr = &MemoryMarshal.GetReference(sig64),
                    sessionPtr = &MemoryMarshal.GetReference(session))
                    {
                        var handles = new GCHandle[count];
                        try
                        {
                            for (int i = 0; i < count; i++)
                            {
                                handles[i] = GCHandle.Alloc(partial_sigs[i], GCHandleType.Pinned);
                                Marshal.WriteIntPtr(nativePtrArray, i * ptrSize, handles[i].AddrOfPinnedObject());
                            }

                            return _musig_partial_sig_agg(_ctx, sig64Ptr, sessionPtr, nativePtrArray, (nuint)count) == 1;
                        }
                        finally
                        {
                            for (int i = 0; i < count; i++)
                            {
                                if (handles[i].IsAllocated)
                                    handles[i].Free();
                            }
                        }
                    }
            }
            finally
            {
                Marshal.FreeHGlobal(nativePtrArray);
            }
        }

